1	#include "Menu.hpp"
2	
3	#include <utility>
4	
5	#include "Config.hpp"  // trim
6	#include "InputMap.hpp"
7	
8	namespace llm_npc {
9	
10	namespace {
11	
12	// Ids used by layout()/update() to identify what was clicked.
13	constexpr int kIdResume = 0;
14	constexpr int kIdControls = 1;
15	constexpr int kIdQuit = 2;
16	constexpr int kIdMultiplayer = 3;
17	constexpr int kIdBack = 100;
18	// Controls-page chips use ids [kIdChipBase, kIdChipBase + kActionCount).
19	constexpr int kIdChipBase = 200;
20	// Multiplayer-page widgets.
21	constexpr int kIdHost = 300;
22	constexpr int kIdAddress = 301;
23	constexpr int kIdJoin = 302;
24	constexpr int kIdLeave = 303;
25	// Creator-page widgets. Field ids map to editingField_ values 1-3; the
26	// part cyclers encode category and direction in their id.
27	constexpr int kIdCreator = 4;
28	constexpr int kIdJournal = 5;
29	// Journal-page widgets.
30	constexpr int kIdJournalPrev = 500;
31	constexpr int kIdJournalNext = 501;
32	constexpr int kJournalRowsPerPage = 7;
33	constexpr int kIdFieldBase = 400;      // +1 name, +2 backstory, +3 traits
34	constexpr int kIdPartPrev = 410;       // +category
35	constexpr int kIdPartNext = 420;       // +category
36	constexpr int kIdPalette = 430;
37	constexpr int kIdRandomize = 431;
38	constexpr int kIdCreate = 432;
39	
40	// Display name for a catalog part id: the text after the category prefix
41	// ("hair_bowl" → "bowl"), title-ish enough for a picker chip.
42	std::string partLabel(const std::string& id) {
43	    const auto underscore = id.find('_');
44	    return underscore == std::string::npos ? id : id.substr(underscore + 1);
45	}
46	
47	const char* categoryLabel(PartCategory category) {
48	    switch (category) {
49	        case PartCategory::Body: return "Body";
50	        case PartCategory::Head: return "Head";
51	        case PartCategory::Eyes: return "Eyes";
52	        case PartCategory::Hair: return "Hair";
53	    }
54	    return "?";
55	}
56	
57	constexpr float kToastSeconds = 3.f;
58	
59	// Default TCP port suggested for hosting; also the port pre-filled in the
60	// join address. Arbitrary high port outside common registered ranges.
61	constexpr int kDefaultHostPort = 40605;
62	
63	// Splits "ip:port" into its parts; false when the port is missing/garbage.
64	bool splitAddress(const std::string& address, std::string& host, int& port) {
65	    const auto colon = address.rfind(':');
66	    if (colon == std::string::npos || colon == 0 || colon + 1 >= address.size()) return false;
67	    host = address.substr(0, colon);
68	    try {
69	        port = std::stoi(address.substr(colon + 1));
70	    } catch (...) {
71	        return false;
72	    }
73	    return port > 0 && port <= 65535;
74	}
75	
76	// Draws `str` horizontally centered inside `rect`.
77	void drawCentered(const std::string& str, int size, const Rectangle& rect, Color color) {
78	    const int width = MeasureText(str.c_str(), size);
79	    DrawText(str.c_str(),
80	             static_cast<int>(rect.x + (rect.width - static_cast<float>(width)) / 2.f),
81	             static_cast<int>(rect.y + (rect.height - static_cast<float>(size)) / 2.f),
82	             size, color);
83	}
84	
85	// Draws `str` centered on the whole screen width at height `y`.
86	void drawCenteredLine(const std::string& str, int size, float y, Color color) {
87	    const int width = MeasureText(str.c_str(), size);
88	    DrawText(str.c_str(), (GetScreenWidth() - width) / 2, static_cast<int>(y), size, color);
89	}
90	
91	}  // namespace
92	
93	Menu::Menu(KeyBindings& bindings, std::filesystem::path savePath)
94	    : bindings_(bindings), savePath_(std::move(savePath)) {}
95	
96	void Menu::setMultiplayer(MultiplayerHooks hooks) { multiplayer_ = std::move(hooks); }
97	
98	void Menu::setCreator(CreatorHooks hooks) { creator_ = std::move(hooks); }
99	
100	void Menu::setJournal(JournalHooks hooks) { journal_ = std::move(hooks); }
101	
102	void Menu::open() {
103	    page_ = Page::Main;
104	    awaiting_.reset();
105	    editingAddress_ = false;
106	    editingField_ = 0;  // draft look and typed fields survive a reopen
107	    toast_.clear();
108	    toastLeft_ = 0.f;
109	}
110	
111	std::vector<Menu::Hit> Menu::layout() const {
112	    const float w = static_cast<float>(GetScreenWidth());
113	    const float h = static_cast<float>(GetScreenHeight());
114	    std::vector<Hit> hits;
115	
116	    if (page_ == Page::Main) {
117	        const float x = (w - 320.f) * 0.5f;
118	        float y = h * 0.5f - 218.f;
119	        for (int id :
120	             {kIdResume, kIdControls, kIdMultiplayer, kIdCreator, kIdJournal, kIdQuit}) {
121	            hits.push_back({Rectangle{x, y, 320.f, 52.f}, id});
122	            y += 72.f;
123	        }
124	    } else if (page_ == Page::Journal) {
125	        // Rows draw in render(); only paging + back are clickable.
126	        const float y = h * 0.86f;
127	        hits.push_back({Rectangle{w * 0.20f, y, 120.f, 44.f}, kIdJournalPrev});
128	        hits.push_back({Rectangle{w * 0.80f - 120.f, y, 120.f, 44.f}, kIdJournalNext});
129	        hits.push_back({Rectangle{(w - 320.f) * 0.5f, y, 320.f, 44.f}, kIdBack});
130	    } else if (page_ == Page::Creator) {
131	        // Left column: persona text fields (label drawn above each box).
132	        const float fieldX = w * 0.07f;
133	        float y = h * 0.26f;
134	        for (int f = 1; f <= 3; ++f) {
135	            hits.push_back({Rectangle{fieldX, y, w * 0.34f, 44.f}, kIdFieldBase + f});
136	            y += 92.f;
137	        }
138	        // Right column: a [<] label [>] row per category, then palette,
139	        // then the action buttons. The preview renders in-world between
140	        // the columns (main.cpp draws it while this page is open).
141	        const float rowX = w * 0.62f;
142	        const float rowW = w * 0.31f;
143	        y = h * 0.26f;
144	        for (int c = 0; c < kPartCategoryCount; ++c) {
145	            hits.push_back({Rectangle{rowX, y, 44.f, 40.f}, kIdPartPrev + c});
146	            hits.push_back({Rectangle{rowX + rowW - 44.f, y, 44.f, 40.f}, kIdPartNext + c});
147	            y += 56.f;
148	        }
149	        hits.push_back({Rectangle{rowX, y, rowW, 40.f}, kIdPalette});
150	        y += 64.f;
151	        hits.push_back({Rectangle{rowX, y, rowW * 0.47f, 48.f}, kIdRandomize});
152	        hits.push_back(
153	            {Rectangle{rowX + rowW * 0.53f, y, rowW * 0.47f, 48.f}, kIdCreate});
154	        hits.push_back({Rectangle{(w - 320.f) * 0.5f, h * 0.86f, 320.f, 48.f}, kIdBack});
155	    } else if (page_ == Page::Multiplayer) {
156	        const float x = (w - 420.f) * 0.5f;
157	        float y = h * 0.30f;
158	        if (multiplayer_.active && multiplayer_.active()) {
159	            hits.push_back({Rectangle{x, y, 420.f, 52.f}, kIdLeave});
160	            y += 72.f;
161	        } else {
162	            hits.push_back({Rectangle{x, y, 420.f, 52.f}, kIdHost});
163	            y += 88.f;
164	            hits.push_back({Rectangle{x, y, 420.f, 44.f}, kIdAddress});
165	            y += 60.f;
166	            hits.push_back({Rectangle{x, y, 420.f, 52.f}, kIdJoin});
167	            y += 72.f;
168	        }
169	        hits.push_back({Rectangle{(w - 320.f) * 0.5f, y + 24.f, 320.f, 52.f}, kIdBack});
170	    } else {
171	        float y = h * 0.24f;
172	        for (std::size_t i = 0; i < kActionCount; ++i) {
173	            hits.push_back({Rectangle{w * 0.5f + 90.f, y, 180.f, 40.f},
174	                            kIdChipBase + static_cast<int>(i)});
175	            y += 52.f;
176	        }
177	        hits.push_back({Rectangle{(w - 320.f) * 0.5f, y + 28.f, 320.f, 52.f}, kIdBack});
178	    }
179	    return hits;
180	}
181	
182	MenuResult Menu::update(float dt) {
183	    if (toastLeft_ > 0.f) {
184	        toastLeft_ -= dt;
185	        if (toastLeft_ <= 0.f) toast_.clear();
186	    }
187	
188	    // Armed key capture eats the keyboard until a key lands or Escape.
189	    if (awaiting_) {
190	        if (IsKeyPressed(KEY_ESCAPE)) {
191	            awaiting_.reset();
192	            showToast("Rebind cancelled");
193	            return MenuResult::None;
194	        }
195	        const int key = GetKeyPressed();
196	        if (key != 0) applyCapture(key);
197	        return MenuResult::None;
198	    }
199	
200	    // Creator field editing: typed characters go into the focused field.
201	    if (editingField_ != 0) {
202	        std::string& field = editingField_ == 1   ? creatorName_
203	                             : editingField_ == 2 ? creatorBackstory_
204	                                                  : creatorTraits_;
205	        const std::size_t cap = editingField_ == 1 ? 32 : 160;
206	        int ch = GetCharPressed();
207	        while (ch != 0) {
208	            if (ch >= 32 && ch < 127 && field.size() < cap) {
209	                field.push_back(static_cast<char>(ch));
210	            }
211	            ch = GetCharPressed();
212	        }
213	        if ((IsKeyPressed(KEY_BACKSPACE) || IsKeyPressedRepeat(KEY_BACKSPACE)) &&
214	            !field.empty()) {
215	            field.pop_back();
216	        }
217	        if (IsKeyPressed(KEY_ESCAPE) || IsKeyPressed(KEY_ENTER)) {
218	            editingField_ = 0;
219	            return MenuResult::None;  // the Escape ends the edit, not the page
220	        }
221	        // Clicking elsewhere also drops focus (fall through to clicks).
222	    }
223	
224	    // Address editing: typed characters go into the field.
225	    if (editingAddress_) {
226	        int ch = GetCharPressed();
227	        while (ch != 0) {
228	            if (ch >= 32 && ch < 127 && joinAddress_.size() < 64) {
229	                joinAddress_.push_back(static_cast<char>(ch));
230	            }
231	            ch = GetCharPressed();
232	        }
233	        if ((IsKeyPressed(KEY_BACKSPACE) || IsKeyPressedRepeat(KEY_BACKSPACE)) &&
234	            !joinAddress_.empty()) {
235	            joinAddress_.pop_back();
236	        }
237	        if (IsKeyPressed(KEY_ESCAPE)) editingAddress_ = false;
238	        if (IsKeyPressed(KEY_ENTER)) {
239	            editingAddress_ = false;
240	            attemptJoin();
241	        }
242	        // Clicking empty space also drops focus (fall through to clicks).
243	    }
244	
245	    if (!editingAddress_ && IsKeyPressed(KEY_ESCAPE)) {
246	        if (page_ != Page::Main) {
247	            page_ = Page::Main;
248	            return MenuResult::None;
249	        }
250	        return MenuResult::Resume;
251	    }
252	
253	    if (IsMouseButtonPressed(MOUSE_BUTTON_LEFT)) {
254	        const Vector2 click = GetMousePosition();
255	        bool hitSomething = false;
256	        for (const Hit& hit : layout()) {
257	            if (!CheckCollisionPointRec(click, hit.rect)) continue;
258	            hitSomething = true;
259	            if (hit.id == kIdResume) return MenuResult::Resume;
260	            if (hit.id == kIdQuit) return MenuResult::Quit;
261	            if (hit.id == kIdControls) {
262	                page_ = Page::Controls;
263	            } else if (hit.id == kIdMultiplayer) {
264	                page_ = Page::Multiplayer;
265	                editingAddress_ = false;
266	            } else if (hit.id == kIdCreator) {
267	                page_ = Page::Creator;
268	                editingField_ = 0;
269	            } else if (hit.id == kIdJournal) {
270	                page_ = Page::Journal;
271	                journalPage_ = 0;
272	            } else if (hit.id == kIdJournalPrev) {
273	                if (journalPage_ > 0) --journalPage_;
274	            } else if (hit.id == kIdJournalNext) {
275	                const int rows = journal_.entries
276	                                     ? static_cast<int>(journal_.entries().size())
277	                                     : 0;
278	                if ((journalPage_ + 1) * kJournalRowsPerPage < rows) ++journalPage_;
279	            } else if (hit.id == kIdBack) {
280	                awaiting_.reset();
281	                editingAddress_ = false;
282	                editingField_ = 0;
283	                page_ = Page::Main;
284	            } else if (hit.id >= kIdFieldBase + 1 && hit.id <= kIdFieldBase + 3) {
285	                editingField_ = hit.id - kIdFieldBase;
286	            } else if (hit.id >= kIdPartPrev && hit.id < kIdPartPrev + kPartCategoryCount) {
287	                editingField_ = 0;
288	                cycleCreatorPart(static_cast<PartCategory>(hit.id - kIdPartPrev), -1);
289	            } else if (hit.id >= kIdPartNext && hit.id < kIdPartNext + kPartCategoryCount) {
290	                editingField_ = 0;
291	                cycleCreatorPart(static_cast<PartCategory>(hit.id - kIdPartNext), +1);
292	            } else if (hit.id == kIdPalette) {
293	                editingField_ = 0;
294	                const auto& palettes = paletteCatalog();
295	                std::size_t index = 0;
296	                for (std::size_t i = 0; i < palettes.size(); ++i) {
297	                    if (palettes[i].id == draftLook_.paletteId) index = i;
298	                }
299	                draftLook_.paletteId = palettes[(index + 1) % palettes.size()].id;
300	            } else if (hit.id == kIdRandomize) {
301	                editingField_ = 0;
302	                creatorSeed_ = creatorSeed_ * 7919u + 13u;
303	                draftLook_ = randomizeLook(creatorSeed_);
304	            } else if (hit.id == kIdCreate) {
305	                editingField_ = 0;
306	                attemptCreate();
307	            } else if (hit.id == kIdHost) {
308	                if (multiplayer_.onHost) {
309	                    const std::string error = multiplayer_.onHost(kDefaultHostPort);
310	                    showToast(error.empty() ? "Hosting started" : error);
311	                }
312	            } else if (hit.id == kIdAddress) {
313	                editingAddress_ = true;
314	            } else if (hit.id == kIdJoin) {
315	                editingAddress_ = false;
316	                attemptJoin();
317	            } else if (hit.id == kIdLeave) {
318	                if (multiplayer_.onLeave) multiplayer_.onLeave();
319	                showToast("Left the session");
320	            } else if (hit.id >= kIdChipBase &&
321	                       hit.id < kIdChipBase + static_cast<int>(kActionCount)) {
322	                awaiting_ = static_cast<Action>(hit.id - kIdChipBase);
323	                toast_.clear();
324	            }
325	            break;
326	        }
327	        // Clicking empty space cancels an armed capture or field edit.
328	        if (!hitSomething) {
329	            awaiting_.reset();
330	            editingAddress_ = false;
331	            editingField_ = 0;
332	        }
333	    }
334	
335	    return MenuResult::None;
336	}
