338	void Menu::applyCapture(int key) {
339	    const std::string name = keyNameOf(key);
340	    if (name.empty()) {
341	        showToast("That key can't be bound");
342	        return;
343	    }
344	    const Action action = *awaiting_;
345	    awaiting_.reset();
346	    const std::optional<Action> displaced = bindings_.rebind(action, name);
347	    if (displaced) {
348	        showToast(std::string("Swapped keys with \"") + KeyBindings::actionLabel(*displaced) +
349	                  "\"");
350	    } else {
351	        showToast(std::string(KeyBindings::actionLabel(action)) + " is now " + name);
352	    }
353	    if (!bindings_.save(savePath_)) {
354	        showToast("Warning: could not save key bindings");
355	    }
356	}
