358	void Menu::cycleCreatorPart(PartCategory category, int direction) {
359	    // Options are gated by the BODY's style family (the body is the style
360	    // anchor); cycling the body itself offers every body, then re-validates
361	    // the other categories against the new family.
362	    const PartDef* body = findPart(draftLook_.part(PartCategory::Body));
363	    const std::string gate =
364	        category == PartCategory::Body ? "any" : (body ? body->styleTag : "any");
365	    const auto options = partsForCategory(category, gate);
366	    if (options.empty()) return;
367	
368	    std::size_t index = 0;
369	    for (std::size_t i = 0; i < options.size(); ++i) {
370	        if (options[i]->id == draftLook_.part(category)) index = i;
371	    }
372	    index = (index + options.size() + static_cast<std::size_t>(direction)) %
373	            options.size();
374	    draftLook_.part(category) = options[index]->id;
375	
376	    if (category == PartCategory::Body) {
377	        const PartDef* newBody = options[index];
378	        for (const CategorySpec& spec : categorySpecs()) {
379	            if (spec.category == PartCategory::Body) continue;
380	            const PartDef* current = findPart(draftLook_.part(spec.category));
381	            if (current && styleCompatible(*newBody, *current)) continue;
382	            const auto valid = partsForCategory(spec.category, newBody->styleTag);
383	            if (!valid.empty()) draftLook_.part(spec.category) = valid.front()->id;
384	        }
385	    }
386	}
