13	
14	LlmClient::LlmClient(LlmConfig config) : config_(std::move(config)) {
15	    worker_ = std::thread(&LlmClient::workerLoop, this);
16	}
17	
18	LlmClient::~LlmClient() {
19	    {
20	        // Setting stop_ under the queue mutex serializes with the worker's
21	        // predicate check: without it, the store+notify can land between the
22	        // worker evaluating the predicate (false) and blocking on the CV — a
23	        // lost wakeup that leaves join() hanging forever.
24	        std::lock_guard<std::mutex> lock(requestMutex_);
25	        stop_.store(true);
26	    }
27	    requestCv_.notify_all();
28	    if (worker_.joinable()) worker_.join();
29	}
30	
31	void LlmClient::enqueue(ChatRequest req) {
32	    {
33	        std::lock_guard<std::mutex> lock(requestMutex_);
34	        requests_.push(std::move(req));
35	    }
36	    requestCv_.notify_one();
37	}
38	
39	std::uint64_t LlmClient::submit(std::string systemPrompt,
40	                                std::vector<ChatTurn> history,
41	                                std::string userMessage) {
42	    ChatRequest req;
43	    req.id = nextId_.fetch_add(1);
44	    req.systemPrompt = std::move(systemPrompt);
45	    req.history = std::move(history);
46	    req.userMessage = std::move(userMessage);
47	
48	    const std::uint64_t id = req.id;
49	    enqueue(std::move(req));
50	    return id;
51	}
52	
53	void LlmClient::warmUp() {
54	    ChatRequest req;
55	    req.id = nextId_.fetch_add(1);
56	    req.internal = true;
57	    enqueue(std::move(req));
58	}
59	
60	std::vector<ChatDelta> LlmClient::drainDeltas() {
61	    std::vector<ChatDelta> out;
62	    std::lock_guard<std::mutex> lock(replyMutex_);
63	    out.swap(deltas_);
64	    return out;
65	}
66	
67	std::vector<ChatReply> LlmClient::drainReplies() {
68	    std::vector<ChatReply> out;
69	    std::lock_guard<std::mutex> lock(replyMutex_);
70	    out.swap(replies_);
71	    return out;
72	}
73	
74	void LlmClient::workerLoop() {
75	    while (true) {
76	        ChatRequest req;
77	        {
78	            std::unique_lock<std::mutex> lock(requestMutex_);
79	            requestCv_.wait(lock, [this] { return stop_.load() || !requests_.empty(); });
80	            if (stop_.load() && requests_.empty()) return;
81	            req = std::move(requests_.front());
82	            requests_.pop();
83	        }
84	
85	        inFlight_.store(true);
86	        ChatReply reply = processOne(req);
87	        if (!req.internal) {
88	            std::lock_guard<std::mutex> lock(replyMutex_);
89	            replies_.push_back(std::move(reply));
90	        }
91	        // Drop the flag only after the reply is queued so UI can poll busy()
92	        // without seeing a brief idle window before the reply lands.
93	        inFlight_.store(false);
94	    }
95	}
96	
97	ChatReply LlmClient::processOne(const ChatRequest& req) {
98	    ChatReply reply;
99	    reply.id = req.id;
100	
101	    // Build Ollama /api/chat body. Streaming NDJSON keeps perceived latency
102	    // low (first words appear immediately); keep_alive holds the model in
103	    // memory between conversations. Warm-up requests send no messages, which
104	    // makes Ollama load the model and return at once.
