136	void DialogUI::render() const {
137	    const float w = static_cast<float>(GetScreenWidth());
138	    const float h = static_cast<float>(GetScreenHeight());
139	
140	    const float transcriptBottom = h - kInputHeight - kPadding;
141	    const std::size_t wrapChars =
142	        std::max<std::size_t>(20, static_cast<std::size_t>((w - 2 * kPadding) / 9.0f));
143	
144	    // Collect wrapped, colored lines from newest backward until we run out of
145	    // vertical space. Then render them in chronological order.
146	    struct RenderedLine {
147	        std::string text;
148	        Color color;
149	    };
150	    std::vector<RenderedLine> rendered;
151	    float used = 0.f;
152	    const float available = transcriptBottom - kPadding;
153	
154	    if (streaming_ && !streamingText_.empty()) {
155	        // Live, partially-streamed NPC line with a cursor.
156	        const std::string prefix = streamingSpeaker_.empty() ? "" : streamingSpeaker_ + ": ";
157	        auto wrapped = wrap(prefix + streamingText_ + "_", wrapChars);
158	        for (auto wi = wrapped.rbegin(); wi != wrapped.rend(); ++wi) {
159	            if (used + kLineHeight > available) break;
160	            rendered.push_back({*wi, colorFor(TranscriptLine::Kind::Npc)});
161	            used += kLineHeight;
162	        }
163	    } else if (thinking_ || streaming_) {
164	        const std::string speaker = streaming_ ? streamingSpeaker_ : thinkingSpeaker_;
165	        std::string indicator = "... " + (speaker.empty() ? std::string("(thinking)")
166	                                                          : speaker + " is thinking...");
167	        rendered.push_back({indicator, Color{140, 140, 140, 255}});
168	        used += kLineHeight;
169	    }
170	
171	    for (auto it = transcript_.rbegin(); it != transcript_.rend(); ++it) {
172	        const auto& line = *it;
173	        std::string prefix = line.speaker.empty() ? "" : line.speaker + ": ";
174	        auto wrapped = wrap(prefix + line.text, wrapChars);
175	        // Reverse push preserves chronological order after the final reverse.
176	        for (auto wi = wrapped.rbegin(); wi != wrapped.rend(); ++wi) {
177	            if (used + kLineHeight > available) break;
178	            rendered.push_back({*wi, colorFor(line.kind)});
179	            used += kLineHeight;
180	        }
181	        if (used + kLineHeight > available) break;
182	    }
183	
184	    std::reverse(rendered.begin(), rendered.end());
185	
186	    float y = transcriptBottom - static_cast<float>(rendered.size()) * kLineHeight;
187	    for (const auto& rl : rendered) {
188	        DrawText(rl.text.c_str(), static_cast<int>(kPadding), static_cast<int>(y),
189	                 kFontSize, rl.color);
190	        y += kLineHeight;
191	    }
192	
193	    // Input box.
194	    const Rectangle box{kPadding, h - kInputHeight - kPadding * 0.5f,
195	                        w - 2 * kPadding, kInputHeight};
196	    DrawRectangleRec(box, Color{30, 30, 36, 255});
197	    DrawRectangleLinesEx(box, 2.f,
198	                         inputEnabled_ ? Color{120, 160, 220, 255} : Color{70, 70, 70, 255});
199	
200	    const std::string prompt = "> " + input_ + (inputEnabled_ ? "_" : "");
201	    DrawText(prompt.c_str(), static_cast<int>(kPadding + 10.f),
202	             static_cast<int>(box.y + 12.f), kFontSize,
203	             inputEnabled_ ? WHITE : Color{120, 120, 120, 255});
204	}
